async function getLeaderboardData() {
  const res = await fetch('http://localhost:4444/leaderboard', {
    cache: 'no-store', 
  });
  if (!res.ok) {
    throw new Error('Failed to fetch data');
  }

  return res.json();
}


const Card = ({ player }) => (
  <div className="card w-10 h-5 flex flex-col items-center justify-center border p-4 m-2">
    <img src={player.profile_img} alt={player.username} />
    <h2>{player.username}</h2>
    <p>XP: {player.xp}</p>
  </div>
);
// 2. Your page component is now async
export default async function LeaderboardPage() {
  const res = await getLeaderboardData();

  return (
    <div>
      <h1>Leaderboard</h1>
      <div className="leaderboard">
        {res.leaderboard.map((player, index) => (
          <Card key={player.username} player={player} />
        ))}
      </div>
    </div>
  );
}
       
          